<div class="table-wrap"><table class="t"><thead><tr><th>Request</th><th>Delivery</th></tr></thead><tbody>
<?php foreach ($items as $d): ?><tr><td><a href="/admin/requests/<?= e($d['request_ref']) ?>"><strong><?= e($d['request_ref']) ?></strong></a><div><?= e($d['name']) ?></div><div class="muted xs"><?= e($d['service']) ?> · <?= e($d['need']) ?></div></td>
<td><form method="post" action="/admin/deliveries/<?= e($d['request_ref']) ?>" class="form" style="grid-template-columns:repeat(5,1fr) auto;align-items:end;gap:8px"><?= csrf_field() ?>
<select name="stage"><?php foreach (['Assigned', 'In progress', 'Delivered', 'Completed', 'Disputed'] as $x) { echo '<option' . ($d['stage'] === $x ? ' selected' : '') . '>' . $x . '</option>'; } ?></select><input name="provider" value="<?= e($d['provider']) ?>" placeholder="Provider"><input name="value" value="<?= e($d['value']) ?>" placeholder="Value"><input name="provider_cost" value="<?= e($d['provider_cost']) ?>" placeholder="Cost"><select name="payment"><?php foreach (PAY_STATUS as $x) { echo '<option' . ($d['payment'] === $x ? ' selected' : '') . '>' . $x . '</option>'; } ?></select><button class="btn btn-ghost btn-xs">Save</button></form></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="2" class="muted center" style="padding:30px">Deliveries are created automatically when a request is marked as Won.</td></tr><?php endif; ?></tbody></table></div>
